-- 0034_jalur_pendidikan.sql
-- Jalur Pendidikan per profesi untuk tab "Jalur Pendidikan" di layar Roadmap.
--
-- Tiap profesi punya 1-2 pilihan jalur: VOKASI (SMK / D3 / D4) dan AKADEMIK
-- (D3 / S1 / S2). Profesi yang menuntut pendidikan lanjut -- dosen dan dokter
-- spesialis -- hanya punya satu jalur karena jalur vokasi tidak berlaku.
--
-- Bidang studi dikurasi per rumpun profesi, dengan penyimpangan per profesi
-- untuk kasus yang bidangnya berbeda dari rumpunnya (Apoteker -> Farmasi,
-- Dokter Gigi -> Kedokteran Gigi, dan seterusnya). Langkah lisensi diambil
-- dari career_licenses yang berjenis WAJIB, diurutkan mengikuti alur nyata:
-- uji kompetensi lebih dulu, baru registrasi, baru izin praktik.

begin;

-- ---------------------------------------------------------------- 1. tabel --

create table if not exists public.education_path_kinds (
  code          text primary key,
  label_id      text not null,
  description_id text not null,
  display_order smallint not null
);

create table if not exists public.career_education_paths (
  id            serial primary key,
  career_id     integer not null references public.careers(id) on delete cascade,
  kind_code     text not null references public.education_path_kinds(code),
  level_code    text not null references public.education_levels(code),
  title_id      text not null,
  tagline_id    text not null,
  years_min     smallint not null,
  years_max     smallint not null,
  cta_label_id  text not null,
  table_label_id text not null,
  display_order smallint not null,
  unique (career_id, kind_code)
);
create index if not exists idx_cep_career
  on public.career_education_paths (career_id, display_order);

create table if not exists public.career_education_path_benefits (
  path_id       integer not null references public.career_education_paths(id) on delete cascade,
  display_order smallint not null,
  text_id       text not null,
  primary key (path_id, display_order)
);

create table if not exists public.career_education_path_steps (
  path_id       integer not null references public.career_education_paths(id) on delete cascade,
  step_order    smallint not null,
  title_id      text not null,
  note_id       text,
  step_rank     smallint,
  step_kind     text not null,
  primary key (path_id, step_order),
  constraint chk_step_kind check (step_kind in
    ('SEKOLAH','KULIAH','ALIH_JENJANG','PROFESI','UJI','LISENSI','SERTIFIKASI',
     'PKL','KERJA','SPESIALISASI','TUJUAN'))
);

-- Pilihan jalur milik pengguna. Satu baris per (pengguna, profesi) supaya
-- pengguna bisa "Ubah jalur lain" tanpa kehilangan pilihan di profesi lain.
create table if not exists public.user_education_path (
  user_id    uuid not null references auth.users(id) on delete cascade,
  career_id  integer not null references public.careers(id) on delete cascade,
  path_id    integer not null references public.career_education_paths(id) on delete cascade,
  chosen_at  timestamptz not null default now(),
  primary key (user_id, career_id)
);

-- ------------------------------------------------------------------ 2. rls --

alter table public.education_path_kinds            enable row level security;
alter table public.career_education_paths          enable row level security;
alter table public.career_education_path_benefits  enable row level security;
alter table public.career_education_path_steps     enable row level security;
alter table public.user_education_path             enable row level security;

do $$
begin
  if not exists (select 1 from pg_policies where schemaname='public'
                 and tablename='education_path_kinds' and policyname='education_path_kinds_read_all') then
    create policy education_path_kinds_read_all on public.education_path_kinds
      for select to anon, authenticated using (true);
  end if;
  if not exists (select 1 from pg_policies where schemaname='public'
                 and tablename='career_education_paths' and policyname='career_education_paths_read_all') then
    create policy career_education_paths_read_all on public.career_education_paths
      for select to anon, authenticated using (true);
  end if;
  if not exists (select 1 from pg_policies where schemaname='public'
                 and tablename='career_education_path_benefits' and policyname='cepb_read_all') then
    create policy cepb_read_all on public.career_education_path_benefits
      for select to anon, authenticated using (true);
  end if;
  if not exists (select 1 from pg_policies where schemaname='public'
                 and tablename='career_education_path_steps' and policyname='ceps_read_all') then
    create policy ceps_read_all on public.career_education_path_steps
      for select to anon, authenticated using (true);
  end if;
  if not exists (select 1 from pg_policies where schemaname='public'
                 and tablename='user_education_path' and policyname='user_education_path_owner') then
    create policy user_education_path_owner on public.user_education_path
      for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
  end if;
end $$;

-- ----------------------------------------------------------------- 3. isi --

on conflict (code) do update
  set label_id = excluded.label_id,
      description_id = excluded.description_id,
      display_order = excluded.display_order;

delete from public.career_education_paths;
