-- --------------------------------------------------------------- 4. tampil --

-- Status langkah ditentukan dari posisi studi pengguna: langkah pendidikan
-- yang rank-nya sudah dilewati berarti SELESAI, yang sedang ditempuh berarti
-- BERLANGSUNG, sisanya BELUM_MULAI. Langkah non-pendidikan (uji, lisensi,
-- kerja) tidak punya rank sehingga selalu BELUM_MULAI sampai ada pencatatan
-- progres tersendiri.
create or replace function public.status_langkah_jalur(
  p_step_rank smallint, p_rank_tercapai integer, p_rank_sedang integer)
returns text language sql immutable as $$
  select case
    when p_step_rank is null then 'BELUM_MULAI'
    when p_rank_tercapai >= p_step_rank then 'SELESAI'
    when p_rank_sedang is not null and p_rank_sedang >= p_step_rank then 'BERLANGSUNG'
    else 'BELUM_MULAI'
  end;
$$;

comment on function public.status_langkah_jalur(smallint, integer, integer) is
  'Status satu langkah jalur pendidikan terhadap posisi studi pengguna.';

create or replace view public.career_education_path_view
with (security_invoker = true) as
select p.id            as path_id,
       p.career_id,
       c.career_name,
       p.kind_code,
       k.label_id      as kind_label,
       p.level_code,
       p.title_id,
       p.tagline_id,
       p.years_min,
       p.years_max,
       p.cta_label_id,
       p.table_label_id,
       p.display_order,
       (select coalesce(jsonb_agg(b.text_id order by b.display_order), '[]'::jsonb)
          from public.career_education_path_benefits b where b.path_id = p.id) as benefits,
       (select coalesce(jsonb_agg(jsonb_build_object(
                 'urutan', s.step_order,
                 'judul',  s.title_id,
                 'catatan', s.note_id,
                 'rank',   s.step_rank,
                 'jenis',  s.step_kind) order by s.step_order), '[]'::jsonb)
          from public.career_education_path_steps s where s.path_id = p.id) as steps
from public.career_education_paths p
join public.education_path_kinds k on k.code = p.kind_code
join public.careers c on c.id = p.career_id;

comment on view public.career_education_path_view is
  'Jalur pendidikan per profesi lengkap dengan keunggulan dan langkahnya.';

-- ------------------------------------------------------------- 5. penjaga --

do $$
declare
  n_profesi int; n_tanpa int; n_path int; n_step int; n_manfaat int; n_salah int;
begin
  select count(*) into n_profesi from public.careers where is_active;
  select count(*) into n_tanpa from public.careers c
   where c.is_active and not exists (
     select 1 from public.career_education_paths p where p.career_id = c.id);
  if n_tanpa > 0 then
    raise exception '0034: % profesi aktif belum punya jalur pendidikan', n_tanpa;
  end if;

  select count(*) into n_path from public.career_education_paths;
  select count(*) into n_step from public.career_education_path_steps;
  select count(*) into n_manfaat from public.career_education_path_benefits;

  -- tiap jalur wajib punya 3 keunggulan
  select count(*) into n_salah from (
    select path_id from public.career_education_path_benefits
    group by path_id having count(*) <> 3) t;
  if n_salah > 0 then
    raise exception '0034: % jalur tidak punya tepat 3 keunggulan', n_salah;
  end if;

  -- tiap jalur wajib diakhiri langkah TUJUAN
  select count(*) into n_salah from public.career_education_paths p
   where not exists (
     select 1 from public.career_education_path_steps s
      where s.path_id = p.id and s.step_kind = 'TUJUAN');
  if n_salah > 0 then
    raise exception '0034: % jalur tidak punya langkah TUJUAN', n_salah;
  end if;

  -- langkah pendidikan wajib naik, tidak boleh turun jenjang
  select count(*) into n_salah from (
    select s.path_id
      from public.career_education_path_steps s
      join public.career_education_path_steps t
        on t.path_id = s.path_id and t.step_order > s.step_order
     where s.step_rank is not null and t.step_rank is not null
       and t.step_rank < s.step_rank) x;
  if n_salah > 0 then
    raise exception '0034: % langkah pendidikan turun jenjang', n_salah;
  end if;

  raise notice '0034: % profesi, % jalur, % langkah, % keunggulan',
    n_profesi, n_path, n_step, n_manfaat;
end $$;

commit;
